    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        ListNode dummy = new ListNode(0);
        ListNode cur = dummy;
        for (int i = 0; i < n; i++) {
            in.nextToken();
            cur.next = new ListNode((int) in.nval);
            cur = cur.next;
        }
        in.nextToken();
        int left = (int) in.nval;
        in.nextToken();
        int right = (int) in.nval;
        ListNode head = reverseBetween(dummy.next, left, right);
        StringBuilder sb = new StringBuilder();
        while (head != null) {
            sb.append(head.val);
            head = head.next;
            sb.append(head != null ? " " : "\n");
        }
        System.out.print(sb);
    }
}
